<script setup lang="ts">
import type { ConnectedMailbox, MailboxMessage } from '../services/connectedMailboxApi'
import {validateReviewedMailboxDraft} from '../../supabase/functions/_shared/mailboxBookingDraft'
const props=defineProps<{workspaceId:string;locale:'es'|'en';bookingId?:string;artists:Array<{id:string;stage_name:string}>}>()
const emit=defineEmits<{created:[bookingId:string]}>()
const api=useConnectedMailbox(),es=computed(()=>props.locale==='es')
const connections=ref<ConnectedMailbox[]>([]),connectionId=ref(''),artistId=ref(''),messages=ref<MailboxMessage[]>([]),selected=ref<MailboxMessage|null>(null),loading=ref(false),busy=ref(false),error=ref(''),hasMore=ref(false)
const analysisConsent=ref(false),selectedConsent=ref(false),analyzingSelected=ref(false),detecting=ref(false),analyzed=ref(false),showAll=ref(false)
const review=reactive({eventDate:'',startTime:'',endTime:'',venue:'',city:'',amount:'',currency:'',contactName:'',contactPhone:'',eventTimezone:''})
const draftWarnings=ref<string[]>([])
const applyExisting=ref(false)
function prepareReview(message:MailboxMessage){const d=message.classification?.draft,b=message.existingBooking;Object.assign(review,{eventDate:d?.eventDate||b?.event_date||'',startTime:d?.startTime||b?.start_time?.slice(0,5)||'',endTime:d?.endTime||b?.end_time?.slice(0,5)||'',venue:d?.venue||b?.venue_name||'',city:d?.city||b?.city||'',amount:d?.offerAmountMinor!=null?String(d.offerAmountMinor/100):b?.offer_amount_minor!=null?String(b.offer_amount_minor/100):'',currency:d?.currency||b?.currency||'',contactName:message.senderName||message.from,contactPhone:b?'':d?.contactPhone||'',eventTimezone:b?.event_timezone||Intl.DateTimeFormat().resolvedOptions().timeZone});draftWarnings.value=d?.warnings||[];applyExisting.value=false;const name=d?.artistName?.trim().toLocaleLowerCase();const matches=name?props.artists.filter(a=>a.stage_name.trim().toLocaleLowerCase()===name):[];artistId.value=b?.artist_id||(matches.length===1?matches[0]!.id:props.artists.length===1?props.artists[0]!.id:'')}
const existingChanges=computed(()=>{const b=selected.value?.existingBooking;if(!b)return [];return [
 [es.value?'Fecha':'Date',b.event_date||'',review.eventDate],
 [es.value?'Hora de inicio':'Start time',b.start_time?.slice(0,5)||'',review.startTime],
 [es.value?'Hora de fin':'End time',b.end_time?.slice(0,5)||'',review.endTime],
 [es.value?'Sala / lugar':'Venue',b.venue_name||'',review.venue],
 [es.value?'Ciudad':'City',b.city||'',review.city],
 [es.value?'Presupuesto':'Offer',b.offer_amount_minor==null?'':String(b.offer_amount_minor/100),String(review.amount)],
 [es.value?'Moneda':'Currency',b.currency||'',review.currency.toUpperCase()],
 [es.value?'Zona horaria':'Timezone',b.event_timezone||'',review.startTime||review.endTime?review.eventTimezone:'']
 ].filter(([,from,to])=>to?.trim()&&from!==to).map(([label,from,to])=>({label,from,to}))})
watch(review,()=>{applyExisting.value=false})
const backgroundEnabled=computed(()=>connections.value.find(c=>c.id===connectionId.value)?.background?.enabled===true)
const shownMessages=computed(()=>showAll.value?messages.value:messages.value.filter(m=>analyzed.value?m.classification?.kind!=='other':Boolean(m.classification)&&m.classification?.kind!=='other'))
let generation=0
function analysisError(e:any){if(e?.message==='mailbox_ai_budget_exhausted')return es.value?'Se ha alcanzado el límite mensual de análisis de esta beta. Puedes revisar los correos y crear solicitudes sin IA.':'The beta monthly analysis limit has been reached. You can review emails and create enquiries without AI.';if(e?.message==='mailbox_ai_quota_exhausted')return es.value?'El análisis con IA está pausado porque se ha agotado su cuota. Puedes crear la solicitud manualmente.':'AI analysis is paused because its quota is exhausted. You can create the request manually.';if(e?.message==='mailbox_ai_rate_limit')return es.value?'La IA ha alcanzado un límite temporal. Prueba más tarde o crea la solicitud manualmente.':'AI has reached a temporary limit. Try later or create the request manually.';if(e?.message==='mailbox_analysis_rate_limit')return es.value?'Espera un minuto antes de volver a analizar.':'Wait one minute before analyzing again.';if(e?.message==='mailbox_ai_not_configured')return es.value?'El análisis con IA todavía no está configurado. Puedes crear la solicitud manualmente.':'AI analysis is not configured yet. You can create the request manually.';if(e?.message==='mailbox_ai_unavailable')return es.value?'El servicio de IA no está disponible. Puedes crear la solicitud manualmente y probar el análisis más tarde.':'The AI service is unavailable. You can create the request manually and try analysis later.';return es.value?'No se pudo analizar este correo. Inténtalo de nuevo.':'This email could not be analyzed. Try again.'}

async function load(){const turn=++generation;loading.value=true;busy.value=false;detecting.value=false;error.value='';showAll.value=showAll.value||analyzed.value;analyzed.value=false;messages.value=[];selected.value=null
 try {const status=await api.status(props.workspaceId,props.bookingId);if(turn!==generation)return;connections.value=status.connections.filter(c=>c.status==='connected'&&(!props.bookingId||status.linkedConnectionIds.includes(c.id)));if(props.bookingId&&!connections.value.length)error.value=status.linkedConnectionIds.length?(es.value?'No se pudo comprobar la conexión de este buzón. Actualiza para intentarlo de nuevo.':'This mailbox connection could not be verified. Refresh to try again.'):(es.value?'Este hilo debe revisarlo la persona que conectó el buzón. Puedes consultar la conversación guardada.':'The person who connected the mailbox must review this thread. You can read the saved conversation.');connectionId.value=connections.value.some(c=>c.id===connectionId.value)?connectionId.value:connections.value[0]?.id||'';if(connectionId.value){const result=props.bookingId?await api.thread(props.workspaceId,connectionId.value,props.bookingId):await api.recent(props.workspaceId,connectionId.value);if(turn===generation){messages.value=result.messages;hasMore.value=result.hasMore}}}
 catch{if(turn===generation)error.value=es.value?'No se pudieron cargar los correos. Actualiza para intentarlo de nuevo.':'Emails could not be loaded. Refresh to try again.'}
 finally{if(turn===generation)loading.value=false}}
async function detectRequests(){if(props.bookingId||!connectionId.value||!analysisConsent.value||busy.value||loading.value)return;const turn=generation;busy.value=true;detecting.value=true;error.value='';try{const result=await api.classify(props.workspaceId,connectionId.value);if(turn!==generation)return;messages.value=result.messages;hasMore.value=result.hasMore;analyzed.value=true;showAll.value=false;selected.value=null}catch(e:any){if(turn===generation){error.value=analysisError(e);showAll.value=true}}finally{if(turn===generation){busy.value=false;detecting.value=false}}}
function changeMailbox(){analysisConsent.value=false;selectedConsent.value=false;analyzed.value=false;showAll.value=Boolean(props.bookingId);void load()}
watch(connectionId,()=>{analysisConsent.value=false;selectedConsent.value=false})
async function analyzeSelected(){if(!selected.value||!selectedConsent.value||busy.value||loading.value)return;const turn=generation,id=selected.value.id;busy.value=true;analyzingSelected.value=true;error.value='';try{const result=await api.classify(props.workspaceId,connectionId.value,id,props.bookingId);if(turn!==generation)return;const message=result.messages.find(m=>m.id===id);if(!message)throw new Error('missing_analysis');messages.value=messages.value.map(m=>m.id===id?message:m);if(selected.value?.id===id){selected.value=message;prepareReview(message)}}catch(e:any){if(turn===generation)error.value=analysisError(e)}finally{analyzingSelected.value=false;if(turn===generation)busy.value=false}}
watch(()=>selected.value?.id,()=>{selectedConsent.value=false;if(selected.value)prepareReview(selected.value)})
async function importMessage(){if(!selected.value||!artistId.value||busy.value)return;busy.value=true;error.value='';try{if(selected.value.existingBooking&&!applyExisting.value){emit('created',selected.value.existingBooking.id);return}const amount=String(review.amount).trim();const reviewed=validateReviewedMailboxDraft({eventDate:review.eventDate||null,startTime:review.startTime||null,endTime:review.endTime||null,venue:review.venue.trim()||null,city:review.city.trim()||null,offerAmountMinor:amount===''?null:Math.round(Number(amount)*100),currency:review.currency.trim().toUpperCase()||null,contactName:review.contactName.trim(),contactPhone:review.contactPhone.trim()||null,eventTimezone:review.startTime||review.endTime?review.eventTimezone.trim()||null:null});const result=await api.importMessage(props.workspaceId,connectionId.value,selected.value.id,artistId.value,props.bookingId,reviewed,applyExisting.value,selected.value.existingBooking?.updated_at);emit('created',result.bookingId);await load()}catch(e:any){error.value=e?.message==='booking_review_stale'?(es.value?'La solicitud ha cambiado mientras revisabas. Analiza de nuevo este correo antes de guardar.':'The enquiry changed while you were reviewing. Analyze this email again before saving.'):e?.message==='booking_time_requires_date'?(es.value?'Añade la fecha completa para guardar el horario.':'Add the full date to save the schedule.'):e?.message==='booking_currency_required'?(es.value?'Indica la moneda del presupuesto.':'Specify the offer currency.'):e?.message==='invalid_booking_draft'?(es.value?'Revisa los datos: fecha, horario, importe y contacto deben ser válidos.':'Check the date, times, amount and contact details.'):es.value?'No se pudo incorporar el correo. Comprueba el artista e inténtalo de nuevo.':'Could not attach this email. Check the artist and retry.'}finally{busy.value=false}}
watch(()=>[props.workspaceId,props.bookingId],()=>{analysisConsent.value=false;analyzed.value=false;showAll.value=Boolean(props.bookingId);void load()},{immediate:true})
watch(()=>props.artists,artists=>{artistId.value=selected.value?.existingBooking?.artist_id||(artists.length===1?artists[0]!.id:'')},{immediate:true})
onBeforeUnmount(()=>generation++)
</script>
<template>
<section v-if="connections.length || error || loading" class="mailbox-requests" :aria-labelledby="bookingId?`mailbox-thread-${bookingId}`:'mailbox-requests-title'">
 <header><div><h2 :id="bookingId?`mailbox-thread-${bookingId}`:'mailbox-requests-title'">{{bookingId?(es?'Correos de esta solicitud':'Emails in this enquiry'):(es?'Solicitudes por correo':'Email enquiries')}}</h2><p>{{bookingId?(es?'Selecciona un correo para revisar sus datos. Guardar cambios no confirma la actuación.':'Select an email to review its details. Saving changes does not confirm the performance.'):(es?'Solo tú ves estos correos. Al crear una solicitud, su conversación se comparte con tu workspace.':'Only you can see these emails. Creating a request shares its conversation with your workspace.')}}</p></div><button type="button" :disabled="loading||busy" @click="load()">{{es?'Actualizar':'Refresh'}}</button></header>
 <label v-if="connections.length>1">{{es?'Buzón':'Mailbox'}}<select v-model="connectionId" :disabled="busy||loading" @change="changeMailbox"><option v-for="c in connections" :key="c.id" :value="c.id">{{c.email}}</option></select></label>
 <p v-if="!bookingId" class="mailbox-requests__hint">{{backgroundEnabled?(es?'Detección automática activa. Las posibles solicitudes de los correos nuevos aparecen aquí para que las revises.':'Automatic detection is active. Possible enquiries from new emails appear here for your review.'):(es?'Activa la detección de correos nuevos en Ajustes o revisa los correos recientes aquí.':'Enable new-email detection in Settings or review recent emails here.')}} {{es?'Últimos 20 mensajes de los últimos 7 días. Crear una solicitud requiere tu revisión.':'Latest 20 messages from the last 7 days. Creating an enquiry requires your review.'}}</p>
 <div v-if="!bookingId" class="mailbox-requests__analysis"><label><input v-model="analysisConsent" type="checkbox" :disabled="busy||loading">{{es?'Autorizo enviar a Groq el asunto y hasta 2.500 caracteres de cada correo reciente para detectar solicitudes. No se envían adjuntos ni se responde automáticamente.':'I authorize sending Groq the subject and up to 2,500 characters of each recent email to detect enquiries. No attachments are sent and no automatic replies are issued.'}}</label><button type="button" :disabled="!analysisConsent||loading||busy" @click="detectRequests">{{detecting?(es?'Detectando…':'Detecting…'):(es?'Detectar solicitudes':'Detect enquiries')}}</button><button type="button" :disabled="loading||busy" @click="showAll=!showAll">{{showAll?(es?'Ocultar otros correos':'Hide other emails'):(es?'Revisar correos sin IA':'Review emails without AI')}}</button></div>
 <p v-if="loading" role="status">{{es?'Cargando correos…':'Loading emails…'}}</p>
 <div v-else class="mailbox-requests__layout"><div class="mailbox-requests__list"><button :disabled="busy" v-for="message in shownMessages" :key="message.id" type="button" :aria-pressed="selected?.id===message.id" @click="selected=message"><span>{{message.senderName}}</span><strong>{{message.subject}}</strong><small v-if="message.classification">{{message.classification.kind==='booking'?(es?'Posible solicitud':'Possible enquiry'):message.classification.kind==='review'?(es?'Por revisar':'Review'):(es?'Otro correo':'Other email')}} · {{message.classification.reason}}</small><small>{{new Date(message.date).toLocaleDateString(locale)}}</small></button><p v-if="!shownMessages.length">{{bookingId?(es?'No hay correos recibidos en esta selección del hilo.':'There are no received emails in this thread selection.'):analyzed?(es?'No se han detectado posibles solicitudes en esta selección. Puedes revisar los demás correos.':'No possible enquiries were detected in this selection. You can review other emails.'):(es?'Detecta posibles solicitudes con IA o revisa los correos sin IA para crear una solicitud.':'Detect possible enquiries with AI or review emails without AI to create a request.')}}</p></div>
 <article v-if="selected"><h3>{{selected.subject}}</h3><p>{{selected.from}}</p><p class="mailbox-requests__body">{{selected.body}}</p><div class="mailbox-requests__analysis"><label><input v-model="selectedConsent" type="checkbox" :disabled="busy||loading">{{es?'Autorizo analizar solo este correo con Groq: asunto y hasta 2.500 caracteres, sin adjuntos.':'I authorize analyzing only this email with Groq: subject and up to 2,500 characters, without attachments.'}}</label><button type="button" :disabled="!selectedConsent||busy||loading" @click="analyzeSelected">{{analyzingSelected?(es?'Analizando…':'Analyzing…'):(es?'Analizar solo este correo':'Analyze only this email')}}</button><p v-if="selected.classification" role="status">{{selected.classification.kind==='booking'?(es?'Posible solicitud':'Possible enquiry'):selected.classification.kind==='review'?(es?'Por revisar':'Review'):(es?'Otro correo':'Other email')}} · {{selected.classification.reason}}</p></div><fieldset class="mailbox-requests__draft" :disabled="busy||loading"><legend>{{es?'Datos de la solicitud':'Enquiry details'}}</legend><p>{{es?'Revisa los datos antes de guardarlos. Esta acción no confirma la actuación ni envía una respuesta.':'Review the details before saving. This action does not confirm a performance or send a reply.'}}</p><p v-for="warning in draftWarnings" :key="warning" class="mailbox-requests__warning">{{warning}}</p><div class="mailbox-requests__fields"><label>{{es?'Nombre del contacto':'Contact name'}}<input v-model="review.contactName" :readonly="Boolean(selected.existingBooking)" maxlength="200" autocomplete="off"></label><label>Email<input :value="selected.from" type="email" readonly></label><label>{{es?'Teléfono · opcional':'Phone · optional'}}<input v-model="review.contactPhone" :readonly="Boolean(selected.existingBooking)" type="tel" maxlength="200"></label><label>{{es?'Fecha':'Date'}}<input v-model="review.eventDate" type="date"></label><label>{{es?'Hora de inicio':'Start time'}}<input v-model="review.startTime" type="time"></label><label>{{es?'Hora de fin':'End time'}}<input v-model="review.endTime" type="time"></label><label v-if="review.startTime||review.endTime">{{es?'Zona horaria · revisa antes de guardar':'Timezone · review before saving'}}<input v-model="review.eventTimezone" maxlength="80" placeholder="Europe/Madrid"></label><label>{{es?'Sala / lugar':'Venue'}}<input v-model="review.venue" maxlength="200"></label><label>{{es?'Ciudad':'City'}}<input v-model="review.city" maxlength="200"></label><label>{{es?'Presupuesto propuesto':'Proposed offer'}}<input v-model="review.amount" type="number" min="0" step="0.01" inputmode="decimal"></label><label>{{es?'Moneda':'Currency'}}<input v-model="review.currency" maxlength="3" placeholder="EUR"></label></div><p>{{selected.existingBooking?(es?'Este correo pertenece a una solicitud existente. Conservamos su contacto, artista y estado.':'This email belongs to an existing enquiry. Its contact, artist and status are preserved.'):(es?'El contacto se guarda con el email del remitente.':'The contact is saved with the sender email.')}}</p></fieldset><div v-if="selected.existingBooking" class="mailbox-requests__existing"><h4>{{es?'Cambios para revisar':'Changes to review'}}</h4><dl v-if="existingChanges.length"><div v-for="change in existingChanges" :key="change.label"><dt>{{change.label}}</dt><dd>{{es?'Actual:':'Current:'}} {{change.from||(es?'Sin dato':'Not set')}} · {{es?'Propuesto:':'Proposed:'}} {{change.to}}</dd></div></dl><p v-else>{{es?'No hay cambios en los datos de la actuación.':'There are no changes to the performance details.'}}</p><label v-if="existingChanges.length"><input v-model="applyExisting" type="checkbox" :disabled="busy||loading">{{es?'Aplicar los cambios que he revisado a esta solicitud. El booking seguirá sin confirmarse automáticamente.':'Apply the changes I have reviewed to this enquiry. The booking will not be confirmed automatically.'}}</label></div><label>{{es?'Artista':'Artist'}}<select v-model="artistId" :aria-label="es?'Artista':'Artist'" :disabled="busy||Boolean(selected.existingBooking)"><option value="">{{es?'Selecciona un artista':'Select an artist'}}</option><option v-for="artist in artists" :key="artist.id" :value="artist.id">{{artist.stage_name}}</option></select></label><button class="mailbox-requests__create" type="button" :disabled="busy||!artistId" @click="importMessage">{{busy&&!analyzingSelected?(es?'Guardando…':'Saving…'):selected.existingBooking?(applyExisting?(bookingId?(es?'Guardar cambios revisados':'Save reviewed changes'):(es?'Guardar cambios y abrir solicitud':'Save changes and open enquiry')):(bookingId?(es?'Volver a la conversación':'Back to conversation'):(es?'Abrir solicitud existente':'Open existing enquiry'))):(es?'Crear solicitud y continuar el hilo':'Create request and continue thread')}}</button></article></div>
 <p v-if="hasMore" class="mailbox-requests__hint">{{bookingId?(es?'Esta revisión muestra hasta 20 mensajes de un hilo vinculado. La conversación guardada sigue disponible debajo.':'This review shows up to 20 messages from one linked thread. The saved conversation remains available below.'):(es?'Hay más correos en tu buzón; esta prueba muestra una selección reciente.':'More emails exist in your mailbox; this pilot displays a recent selection.')}}</p>
 <p v-if="error" class="mailbox-requests__error" role="alert">{{error}}</p>
</section>
</template>
<style scoped>
.mailbox-requests__existing{margin:16px 0;padding:14px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-panel)}.mailbox-requests__existing h4{margin:0 0 12px;font-size:13px}.mailbox-requests__existing dl{display:grid;gap:10px;margin:0 0 14px}.mailbox-requests__existing dt{font-size:12px;color:var(--cue-text)}.mailbox-requests__existing dd{margin:4px 0 0;font-size:12px;color:var(--cue-muted);overflow-wrap:anywhere}.mailbox-requests__existing label{display:flex;align-items:start;line-height:1.5}.mailbox-requests__existing input{accent-color:var(--cue-accent);width:18px;height:18px;flex-shrink:0}
:global([data-theme='light']) .mailbox-requests__fields input{color-scheme:light}
.mailbox-requests__draft{margin:18px 0;padding:16px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-panel);min-width:0}.mailbox-requests__draft legend{font-size:13px;color:var(--cue-text);padding:0 6px}.mailbox-requests__fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.mailbox-requests__fields input{box-sizing:border-box;min-width:0;width:100%;min-height:44px;padding:8px 10px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);background:var(--cue-raised);color:var(--cue-text);font:inherit;color-scheme:dark}.mailbox-requests__fields input:focus-visible{outline:2px solid var(--cue-accent);outline-offset:3px}.mailbox-requests__fields input[readonly]{color:var(--cue-muted)}.mailbox-requests__warning{border-left:3px solid #d9a84e;padding:8px 12px;background:color-mix(in srgb,#d9a84e 8%,transparent)}@media(max-width:680px){.mailbox-requests__fields{grid-template-columns:1fr}}
.mailbox-requests{padding:20px;margin:0 0 24px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-panel);background:var(--cue-surface)}header{display:flex;align-items:start;justify-content:space-between;gap:16px}h2{font-size:17px;margin:0 0 8px}h3{font-size:15px;overflow-wrap:anywhere}p{font-size:12px;line-height:1.5;color:var(--cue-muted)}.mailbox-requests__analysis{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.mailbox-requests__analysis label{display:flex;align-items:start;font-size:12px;line-height:1.5;flex-basis:100%}.mailbox-requests__analysis input{accent-color:var(--cue-accent);width:18px;height:18px;flex-shrink:0}
button,select{min-height:44px;padding:8px 12px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);background:var(--cue-raised);color:var(--cue-text);font-size:12px;cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,select:focus-visible{outline:2px solid var(--cue-accent);outline-offset:3px}.mailbox-requests__layout{display:grid;grid-template-columns:minmax(200px,1fr) minmax(0,1.5fr);gap:20px}.mailbox-requests__list{display:grid;align-content:start;gap:6px;max-height:430px;overflow:auto}.mailbox-requests__list button{display:grid;gap:5px;text-align:left;overflow-wrap:anywhere}.mailbox-requests__list button[aria-pressed=true]{border-color:var(--cue-accent)}small,span{font-size:11px;color:var(--cue-muted)}article{min-width:0}.mailbox-requests__body{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;color:var(--cue-text)}label{display:grid;gap:6px;font-size:12px}.mailbox-requests__create{margin-top:14px;background:var(--cue-accent);color:#080808}.mailbox-requests__error{border-left:3px solid #e65e6a;padding:12px;background:color-mix(in srgb,#e65e6a 8%,transparent)}.mailbox-requests__hint{font-size:11px}@media(max-width:680px){.mailbox-requests{padding:14px}.mailbox-requests__layout{grid-template-columns:1fr}header{flex-wrap:wrap}.mailbox-requests__list{max-height:240px}}
</style>
